            cf = QTextCharFormat()
            cf.setFont(font, SPECIFIED)
            if fg:
                cf.setForeground(QColor(fg))
            if italic:
                cf.setFontItalic(True)
            if strike:
                cf.setFontStrikeOut(True)
            if pill:
                cf.setBackground(TRANSPARENT)
            if href:
                cf.setAnchor(True)
                cf.setAnchorHref(href)
