        self.fn, self.sw, self.sh, self.tid, self.kind = fn, w, h, tid, kind

    def natural_w(self, m: Measurer) -> int:
        return self.sw

    def layout(self, x: int, y: int, w: int, m: Measurer) -> int:
        self.x, self.y, self.w, self.h = x, y, w, self.sh
        return self.h

