Json = Dict[str, Any]


def recents() -> List[str]:
    """Recent projects first, then the folders of the listed sessions, eight at most."""
    out: List[str] = []
    for p in (store.config or {}).get("recentProjects") or []:
        if p and p not in out:
            out.append(str(p))
    for s in store.sessions:
        if len(out) >= 10:
            break
        p = str(s.get("project") or s.get("cwd") or "")
        if p and p not in out:
            out.append(p)
    return out[:8]


def _field_bg(t: theme.Tokens) -> QColor:
    """``.ns-folder``: fill-1 over the sheet."""
    return theme.blend(t.fill_1, sheet_bg(t).name())


def _field_line(t: theme.Tokens) -> QColor:
    return theme.blend(t.hair, _field_bg(t).name())


class NewSessionSheet(Sheet):
