            self.kbd = Keys(str(it["kbd"]), bare=True, parent=self)
            self._kbd_w = self.kbd.sizeHint().width()
        self.setMinimumHeight(30)
        bind(theme.theme.changed, self, lambda _t: self.update())

    @property
