    else if (rec.startsWith('# branch.upstream ')) info.upstream = rec.slice(18);
    else if (rec.startsWith('# branch.ab ')) {
      const m = rec.match(/\+(\d+) -(\d+)/);
      if (m) [info.ahead, info.behind] = [Number(m[1]), Number(m[2])];
