    'dispatch.remove': ({ id, removeWorktrees }) => dispatch.dispatch.remove(str(id, 'id'), { removeWorktrees: Boolean(removeWorktrees) }),
    'dispatch.plan': (p) => {
      need(p.targets === undefined || Array.isArray(p.targets), 'targets');
