    if (res.status >= 400) return { ok: false, error: `The gateway answered HTTP ${res.status}` };
    let doc;
    try {
      doc = JSON.parse(res.body);
    } catch {
      return { ok: false, notHere: true, error: `${listUrl} did not answer with JSON` };
