            if (e.key === 'ArrowDown') {
              e.preventDefault();
              setIdx((i) => Math.min(items.length - 1, i + 1));
            } else if (e.key === 'ArrowUp') {
              e.preventDefault();
              setIdx((i) => Math.max(0, i - 1));
            } else if (e.key === 'Enter') {
              e.preventDefault();
              run(items[idx]);
            }
          }}
        />
      </div>
      <div className="pal-list" ref={list} role="listbox" id={listId} aria-label="Results">
        {items.map((c, i) => {
          const head = c.group !== lastGroup ? c.group : null;
