          onConfirm: (checked) => deleteSession(s.id, checked),
        }),
    },
  ];
  return (
    <div
      className={`side-row${active ? ' active' : ''}${unread && !active ? ' unread' : ''}${menuAt ? ' menu-open' : ''}${indent ? ' sub' : ''}`}
      data-sid={s.id}
      onContextMenu={(e) => {
        if (renaming) return;
        e.preventDefault();
        setMenuAt({ x: e.clientX, y: e.clientY });
      }}
    >
      <button className="side-row-main" onClick={() => openSession(s.id)}>
        <span className="side-row-text">
          {renaming ? (
            <input aria-label="Session title"
              className="input side-rename"
              autoFocus
              value={title}
              onClick={(e) => e.stopPropagation()}
              onChange={(e) => setTitle(e.target.value)}
              onBlur={() => {
