    <>
      {groups.map((g) =>
        g.kind === 'steps' ? (
          <Steps key={g.key} items={g.items} ctx={ctx} />
        ) : (
          <ItemView key={g.key} item={g.item} rev={g.item.rev} ctx={ctx} />
