  box-shadow: inset 0 0 0 1px var(--hair-3), 0 0 0 3px var(--fill-1);
}
.input.mono {
  font-size: var(--fs-small-plus);
}

.field {
  display: grid;
  gap: var(--sp-1_75);
}
.field > label {
  font-size: var(--fs-small);
  font-weight: 550;
  color: var(--text-2);
}
.hint {
  font-size: var(--fs-small);
  color: var(--text-3);
  line-height: 1.5;
}

/* iOS-style switch */
.switch {
  position: relative;
  width: 34px;
  height: 20px;
  border-radius: var(--r-4);
  background: var(--switch-off);
  flex: none;
}
.switch::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-ink);
  box-shadow: var(--shadow-knob);
}
/* On = lit amber track; the knob stays white in both states so "off" can never read as "on". */
.switch.on {
