}
.badge.ok {
  color: var(--ok);
  background: var(--ok-wash);
}
.badge.err {
  color: var(--err);
  background: var(--err-wash);
}
.badge.plan {
  color: var(--plan);
  background: var(--plan-wash);
}
.badge.info {
  color: var(--info);
  background: var(--info-wash);
}

.num-add,
.num-del {
  font-family: var(--font-mono);
  font-size: var(--fs-micro-plus);
  font-variant-numeric: tabular-nums;
}
.num-add {
