.queue-btn.icon {
  width: 24px;
  padding: 0;
  justify-content: center;
}
.queue-btn:hover {
  background: var(--fill-2);
  color: var(--text);
}
.queue-btn:first-child:hover {
  color: var(--accent-text);
}
