/* ================================================================ side panel
   Lives on the chrome surface like the sidebar. Tabs are text with a sliding underline;
   each tab has one toolbar row of borderless controls. */

.panel {
  flex: 0 1 auto;
  min-width: 300px;
  /* Never wider than the conversation in a small window, never above 40% of a big one. */
  max-width: max(300px, min(40vw, calc(100vw - 760px)));
  display: flex;
  flex-direction: column;
  background: var(--canvas);
  container-type: inline-size;
}
/* The panel gives way before the conversation does: in a narrow window it shrinks (down to 300px)
   instead of pushing past the window edge. */
.panel-shell {
  flex: 0 1 auto;
  min-width: 0;
  display: flex;
  min-height: 0;
  background: var(--chrome);
}

.panel-tabs {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--sp-0_5);
  height: var(--header-h);
  padding: 0 var(--sp-2) 0 var(--sp-2_5);
  box-shadow: inset 0 -1px 0 var(--hair);
  overflow-x: auto;
  scrollbar-width: none;
}
.panel-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_5);
  height: 30px;
  padding: 0 var(--sp-2);
  border-radius: var(--r-2);
  font-size: var(--fs-ui);
  color: var(--text-3);
  white-space: nowrap;
}
.panel-tab:hover {
  color: var(--text);
  background: var(--fill-1);
}
.panel-tab.on {
  color: var(--text);
  font-weight: 550;
}
.panel-tab-ico {
  flex: none;
  opacity: 0.85;
}
.panel-tab.on .panel-tab-ico {
  opacity: 1;
}
.panel-ink {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  border-radius: 2px 2px 0 0;
  background: var(--text);
  pointer-events: none;
  z-index: 1;
}
.tab-count {
  min-width: 16px;
  height: 16px;
  padding: 0 var(--sp-1);
  border-radius: var(--r-3);
  background: var(--fill-3);
  color: var(--text);
  font-size: var(--fs-tiny-plus);
  font-weight: 600;
  display: grid;
  place-items: center;
}
/* In a narrow panel only the chosen tab keeps its name; the others are icons with tooltips. The name
   grows in and the ink follows, so switching tabs reads as one movement. */
@container (max-width: 759px) {
  .panel-tab:not(.on) .panel-tab-label {
    display: none;
  }
  .panel-tab:not(.on) {
    width: 34px;
    justify-content: center;
    padding: 0;
  }
  .panel-tab.on {
    padding: 0 var(--sp-2_5) 0 var(--sp-2);
}
}

.panel-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.panel-body > * {
  flex: 1;
  min-height: 0;
}
.panel-keep {
  flex-direction: column;
  min-height: 0;
}
.panel-keep > * {
  flex: 1;
  min-height: 0;
}

.panel-toolbar {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  min-height: 42px;
  padding: var(--sp-1_5) var(--sp-2_5) var(--sp-1_5) var(--sp-3);
  box-shadow: inset 0 -1px 0 var(--hair);
  overflow-x: auto;
  scrollbar-width: none;
  font-size: var(--fs-small);
}
.panel-toolbar .btn.sm {
  height: 26px;
}

.panel .empty {
  padding: var(--sp-10) var(--sp-7);
}

/* ---------------------------------------------------------------- changes */

.changes {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.changes-bar {
  gap: var(--sp-1_5);
}
.changes-scope {
  font-weight: 550;
  color: var(--text);
  white-space: nowrap;
}
.select-btn.ghost-select {
  max-width: 200px;
}
.changes-stat {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_5);
  margin-left: var(--sp-1);
  font-size: var(--fs-small);
  white-space: nowrap;
}
.changes-summary {
  flex: none;
